// kaiten-mcp-server/dist/utils.js
var MAX_RESPONSE_LENGTH = 1e5;
function truncateResponse(text, maxLength = MAX_RESPONSE_LENGTH) {
  if (text.length <= maxLength) {
    return text;
  }
  const truncated = text.slice(0, maxLength);
  const originalLength = text.length;
  const truncatedChars = originalLength - maxLength;
  return truncated + `

\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
\u26A0\uFE0F  RESPONSE TRUNCATED
Original length: ${originalLength.toLocaleString()} characters
Truncated: ${truncatedChars.toLocaleString()} characters
Showing: ${maxLength.toLocaleString()} characters (~${Math.round(maxLength / 4).toLocaleString()} tokens)

\u{1F4A1} To reduce response size:
   \u2022 Use more specific filters (board_id, space_id, column_id)
   \u2022 Reduce the limit parameter (current results may exceed limit)
   \u2022 Use verbosity: 'minimal' for compact output
   \u2022 Search in smaller time ranges (created_after, updated_after)
\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500`;
}
function applyCardVerbosityMinimal(cards) {
  return cards.map((card) => ({
    id: card.id,
    title: card.title,
    board_id: card.board_id,
    owner_name: card.owner?.full_name || null
  }));
}
function applyCardVerbosityNormal(cards, simplifyFn) {
  return cards.map(simplifyFn);
}
function applyCardVerbosityDetailed(cards) {
  return cards;
}
function applyCardVerbosity(cards, verbosity = "normal", simplifyFn) {
  switch (verbosity) {
    case "minimal":
      return applyCardVerbosityMinimal(cards);
    case "detailed":
      return applyCardVerbosityDetailed(cards);
    case "normal":
    default:
      return applyCardVerbosityNormal(cards, simplifyFn);
  }
}
function applyUserVerbosity(users, verbosity = "normal") {
  switch (verbosity) {
    case "minimal":
      return users.map((u) => ({ id: u.id, full_name: u.full_name }));
    case "detailed":
      return users;
    case "normal":
    default:
      return users.map((u) => ({
        id: u.id,
        full_name: u.full_name,
        email: u.email,
        username: u.username,
        activated: u.activated
      }));
  }
}
function applyBoardVerbosity(boards, verbosity = "normal") {
  switch (verbosity) {
    case "minimal":
      return boards.map((b) => ({ id: b.id, title: b.title }));
    case "detailed":
      return boards;
    case "normal":
    default:
      return boards.map((b) => ({
        id: b.id,
        title: b.title,
        space_id: b.space_id,
        archived: b.archived
      }));
  }
}
function formatAsMarkdown(data, title) {
  if (typeof data === "string") {
    return data;
  }
  let markdown = "";
  if (title) {
    markdown += `# ${title}

`;
  }
  if (Array.isArray(data)) {
    markdown += `Found ${data.length} items:

`;
    data.forEach((item, index) => {
      markdown += `## Item ${index + 1}
`;
      markdown += formatObjectAsMarkdown(item);
      markdown += "\n";
    });
    return markdown;
  }
  return formatObjectAsMarkdown(data);
}
function formatObjectAsMarkdown(obj) {
  let markdown = "";
  for (const [key, value] of Object.entries(obj)) {
    if (value === null || value === void 0)
      continue;
    const label = key.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());
    if (typeof value === "object" && !Array.isArray(value)) {
      markdown += `
**${label}:**
`;
      markdown += formatObjectAsMarkdown(value);
    } else if (Array.isArray(value)) {
      markdown += `**${label}:** ${value.join(", ")}
`;
    } else {
      markdown += `**${label}:** ${value}
`;
    }
  }
  return markdown;
}
function applyResponseFormat(data, format = "markdown", title) {
  if (format === "markdown") {
    return typeof data === "string" ? data : formatAsMarkdown(data, title);
  }
  return JSON.stringify(data, null, 2);
}

// kaiten-mcp-server/dist/index.js
var API_URL = config.KAITEN_API_URL;
var API_TOKEN = config.KAITEN_API_TOKEN;
var DEFAULT_SPACE_ID = config.KAITEN_DEFAULT_SPACE_ID;
if (DEFAULT_SPACE_ID) {
  safeLog.info(`Using default space ID: ${DEFAULT_SPACE_ID}`);
}
var kaitenClient = new KaitenClient(API_URL, API_TOKEN);
var mcpLogger = logger.getMCPLogger();
function simplifyUser(user) {
  return {
    id: user.id,
    full_name: user.full_name,
    email: user.email,
    username: user.username,
    activated: user.activated
  };
}
function simplifySpace(space) {
  return {
    id: space.id,
    title: space.title,
    archived: space.archived,
    boards: space.boards?.map((b) => ({
      id: b.id,
      title: b.title
    })) || []
  };
}
function simplifyComment(comment) {
  return {
    id: comment.id,
    text: comment.text,
    created: comment.created,
    updated: comment.updated,
    author_id: comment.author?.id,
    author_name: comment.author?.full_name
  };
}
function simplifyCard(card) {
  const baseUrl = API_URL.replace("/api/latest", "");
  const spaceId = card.space_id || card.board?.space_id || DEFAULT_SPACE_ID || "";
  const cardUrl = `${baseUrl}/space/${spaceId}/card/${card.id}`;
  const blockInfo = card.blocked && card.blockers && card.blockers.length > 0 ? {
    blocked: true,
    block_reason: card.blockers[0].reason || null,
    blocked_at: card.blockers[0].created || null,
    blocker_name: card.blockers[0].blocker?.full_name || null
  } : { blocked: false, block_reason: null, blocked_at: null, blocker_name: null };
  const lastCommentDate = card.comment_last_added_at || null;
  return {
    id: card.id,
    title: card.title,
    url: cardUrl,
    description: card.description || null,
    created: card.created,
    updated: card.updated,
    state: card.state,
    owner_id: card.owner?.id || null,
    owner_name: card.owner?.full_name || null,
    board_id: card.board_id,
    board_title: card.board?.title || null,
    column_id: card.column_id,
    column_title: card.column?.title || null,
    lane_id: card.lane_id,
    lane_title: card.lane?.title || null,
    type_id: card.type_id,
    type_name: card.type?.name || null,
    comments_total: card.comments_total || 0,
    last_comment_date: lastCommentDate,
    tags: card.tags?.map((t) => t.name) || [],
    members: card.members?.map((m) => m.full_name) || [],
    asap: card.asap || false,
    ...blockInfo,
    archived: !!card.archived,
    size: card.size || null,
    due_date: card.due_date || null
  };
}
function simplifyCardCompact(card) {
  const baseUrl = API_URL.replace("/api/latest", "");
  const spaceId = card.space_id || card.board?.space_id || DEFAULT_SPACE_ID || "";
  const cardUrl = `${baseUrl}/space/${spaceId}/card/${card.id}`;
  return {
    id: card.id,
    title: card.title,
    url: cardUrl,
    board_title: card.board?.title || null,
    owner_name: card.owner?.full_name || null,
    updated: card.updated,
    asap: card.asap || false,
    blocked: !!card.blocked
  };
}
